from svgkit import *

def box(x, y, w, h, lines, col, fop=.14):
    o = [rect(x, y, w, h, col, fop, rx=14)]
    n = len(lines); cy = y + h / 2 - (n - 1) * 12
    for k, s in enumerate(lines):
        o.append(t(x + w / 2, cy + k * 24 + 6, s, col if col != 'violet' else 'moon', 17, 'middle'))
    return o

# Fig A: decision flow after a loss
